<?php require BASE_PATH.'/resources/views/inventory/components.php'; ?>
<section class="page-heading inventory-heading"><div><h1>Stock movements</h1><p>Posted entries are immutable. Correct mistakes with a linked reversal or a new adjustment.</p></div><div class="product-actions"><?php inventoryActions(); ?></div></section><?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?>
<form method="get" action="index.php" class="inventory-filters"><input type="hidden" name="route" value="/inventory/movements"><?php if(!empty($filters['product_id'])): ?><input type="hidden" name="product_id" value="<?= (int)$filters['product_id'] ?>"><?php endif; ?><label class="inventory-search">Search<input name="q" placeholder="Product, SKU or reference" value="<?= e($filters['q']??'') ?>"></label><label>Movement type<select name="type"><option value="">All movements</option><?php foreach(['opening'=>'Opening Stock','stock_in'=>'Stock In','stock_out'=>'Stock Out','adjustment_increase'=>'Adjustment Increase','adjustment_decrease'=>'Adjustment Decrease','reversal'=>'Reversal','adjustment'=>'Legacy Adjustment','damage'=>'Legacy Damage','purchase'=>'Legacy Purchase','sale'=>'Legacy Sale','supplier_return'=>'Legacy Supplier Return','customer_return'=>'Legacy Customer Return'] as $v=>$label): ?><option value="<?= $v ?>" <?= ($filters['type']??'')===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>From<input type="date" name="from" value="<?= e($filters['from']??'') ?>"></label><label>To<input type="date" name="to" value="<?= e($filters['to']??'') ?>"></label><label>Performed by<select name="user_id"><option value="">All users</option><?php foreach($actors as $actor): ?><option value="<?= (int)$actor['id'] ?>" <?= (string)($filters['user_id']??'')===(string)$actor['id']?'selected':'' ?>><?= e($actor['name']) ?></option><?php endforeach; ?></select></label><label>Sort<select name="sort"><option value="date">Posted date</option><option value="quantity" <?= ($filters['sort']??'')==='quantity'?'selected':'' ?>>Quantity change</option></select></label><label>Direction<select name="direction"><option value="desc">Newest / highest first</option><option value="asc" <?= ($filters['direction']??'')==='asc'?'selected':'' ?>>Oldest / lowest first</option></select></label><button class="button">Apply</button><a class="button" href="<?= e(url('/inventory/movements')) ?>">Clear</a></form>
<p class="subtle-text"><?= $history['total'] ?> recorded movements · date filters use entry date; sort uses posting time.</p>
<div class="surface table-scroll inventory-table-wrap"><table class="inventory-table history-table"><thead><tr><th>Posted / Entry date</th><th>Product / SKU</th><th>Movement</th><th>Change</th><th>Previous → Resulting</th><th>Cost / item</th><th>Reason</th><th>Reference number</th><th>Notes</th><th>Performed by</th><th>Details</th></tr></thead><tbody><?php foreach($history['rows'] as $m): ?><tr><td data-label="Posted / Entry date"><?= e(local_datetime($m['created_at'])) ?><small><?= e($m['entry_date']??substr($m['created_at'],0,10)) ?></small></td><td data-label="Product / SKU"><strong><?= e($m['name']) ?></strong><small><?= e($m['sku']) ?></small></td><td data-label="Movement"><?= e(App\Services\StockService::label($m)) ?><?php if($m['reverses_movement_id']): ?><small><a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$m['reverses_movement_id'] ?>">Reverses #<?= (int)$m['reverses_movement_id'] ?></a></small><?php endif; ?><?php if($m['reversed_by']): ?><small><a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$m['reversed_by'] ?>">Reversed by #<?= (int)$m['reversed_by'] ?></a></small><?php endif; ?></td><td data-label="Quantity change"><?= $m['quantity_delta']>0?'+':'' ?><?= quantity($m['quantity_delta']) ?></td><td data-label="Previous → Resulting"><?= quantity($m['previous_stock']) ?> → <?= quantity($m['resulting_stock']) ?></td><td data-label="Cost per item"><?= money($m['unit_cost']) ?></td><td data-label="Reason"><?= e($m['reason']??'Not recorded') ?></td><td data-label="Reference number"><?= e($m['reference_id']??'—') ?></td><td data-label="Notes" class="inventory-note"><?= e($m['note']??'—') ?></td><td data-label="Performed by"><?= e($m['actor_name']) ?></td><td data-label="Details"><a class="button button-small" href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$m['id'] ?>">View #<?= (int)$m['id'] ?></a></td></tr><?php endforeach; ?></tbody></table><?php if(!$history['rows']): ?><div class="empty-state compact"><h3>No matching movements</h3><p>Change filters or post an authorised stock entry.</p></div><?php endif; ?></div><?php inventoryPager($history,$filters,'/inventory/movements'); ?>
